code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    horizontal = [r for r in range(h) if sum(v == 2 for v in grid[r]) >= w * 0.5]
    vertical = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= h * 0.5]
    # The long 2-lines mark the rails; motion is perpendicular to them.
    vertical_rails = len(vertical) > len(horizontal)
    sources = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr, cc in ((r-1,c-1),(r-1,c),(r-1,c+1),
                               (r,c-1),(r,c+1),
                               (r+1,c-1),(r+1,c),(r+1,c+1))
            ):
                sources.append((r,c))
    for r, c in sources:
        if vertical_rails:
            for x in range(w):
                if grid[r][x] == 0:
                    out[r][x] = 1
            targets = [(r, x) for x in vertical if x != c]
        else:
            for y in range(h):
                if grid[y][c] == 0:
                    out[y][c] = 1
            targets = [(y, c) for y in horizontal if y != r]
        for y, x in targets:
            for yy in range(max(0, y-1), min(h, y+2)):
                for xx in range(max(0, x-1), min(w, x+2)):
                    if (yy, xx) != (y, x):
                        out[yy][xx] = 1
    return out
'''
